function populateHelpPanel() {
  const controlsList = document.getElementById('controlsList');
  gameControls.forEach(control => {
    const listItem = document.createElement('li');
    if (control.key) {
      listItem.textContent = `Key: ${control.key} - Action: ${control.action}`;
    } else if (control.mouse) {
      listItem.textContent = `Mouse: ${control.mouse} - Action: ${control.action}`;
    }
    controlsList.appendChild(listItem);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  populateHelpPanel();
});

